output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "Customers are obliged to take the available cart from the entrance cart bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Customers are prohibited from taking shelf items unless they are currently pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart",
        "without_cart": {
          "not": "cart_in_possession"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are prohibited from carrying merchandise by hand rather than transporting it in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "hands_free": {
          "not": "handFull"
        }
      },
      "events": {
        "become_hand_loaded": {
          "pre": "hands_free",
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "leave_cart_only_front",
    "text": "Customers are prohibited from abandoning a cart anywhere except the front cart-return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "front_cart_return_bay": "at(0,1)",
        "not_front_cart_return_bay": {
          "not": "front_cart_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_front_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "return_cart_before_exit",
    "text": "After taking a cart, customers are obliged to park it in the front cart-return bay before exiting.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "front_cart_return_bay": "at(0,1)",
        "cart_parked_at_front": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_front": {
          "pre": {
            "and": [
              "front_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "no_exit_until_cart_parked",
    "text": "Customers are prohibited from exiting unless the cart is parked at the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_front": "cartAt(0,1)",
        "cart_not_parked_at_front": {
          "not": "cart_parked_at_front"
        }
      },
      "events": {
        "exit_without_returned_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_parked_at_front"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_without_returned_cart"
    }
  },
  {
    "id": "exit_unencumbered",
    "text": "Customers are prohibited from leaving the store while pushing a cart or carrying an item by hand.",
    "abstraction": {
      "state_properties": {
        "encumbered": {
          "or": [
            "hasCart",
            "handFull"
          ]
        },
        "unencumbered": {
          "not": "encumbered"
        }
      },
      "events": {
        "encumbered_exit": {
          "pre": {
            "and": [
              "EXIT",
              "encumbered"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "encumbered_exit"
    }
  },
  {
    "id": "do_not_push_cart_from_return_bay",
    "text": "Once a customer reaches the front return bay while holding a cart, they are prohibited from pushing the cart away instead of leaving it there.",
    "abstraction": {
      "state_properties": {
        "front_return_with_cart": {
          "and": [
            "at(0,1)",
            "hasCart"
          ]
        },
        "cart_move_action": {
          "or": [
            "N",
            "S",
            "E",
            "W"
          ]
        }
      },
      "events": {
        "push_cart_away_from_return_bay": {
          "pre": {
            "and": [
              "front_return_with_cart",
              "cart_move_action"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_away_from_return_bay"
    }
  }
]
